contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run with an input amount to send to c when calling play
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Observe bank before call
        address bankBefore = c.bank();
        // Observe balances before
        uint balCBefore = address(c).balance;
        uint balThisBefore = address(this).balance;

        bool reverted;
        // Call play and capture revert status
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe bank and balances after
        address bankAfter = c.bank();
        uint balCAfter = address(c).balance;
        uint balThisAfter = address(this).balance;

        // General rule: if call did not revert and the sent amount equals the ticket amount,
        // then bank address is immutable and total Ether (c + this) is conserved by the call.
        assert(
            !(reverted == false && amount == C(address(c)).TICKET_AMOUNT()) ||
            (bankBefore == bankAfter && (balCAfter + balThisAfter == balCBefore + balThisBefore))
        );
    }

    receive() external payable {}
