contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the payment amount as parameter
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record before-values
        uint pot_before = c.pot();
        uint bal_before = address(c).balance;

        // call play and catch revert
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint pot_after = c.pot();
        uint bal_after = address(c).balance;

        // The general rule (only one assert):
        // If the call reverted, nothing else is constrained here.
        // If it did not revert, then amount must have been accepted (==10 by contract design),
        // and exactly one of two situations holds:
        // 1) A payout happened: pot became 0 and contract balance decreased by exactly 1 (the fee)
        // 2) No payout: pot increased by amount and contract balance increased by amount
        assert(
            reverted || (
                // ensure call succeeded implies either payout or accumulation
                (
                    // payout happened: pot reset to 0 and balance decreased by FEE_AMOUNT (1)
                    pot_after == 0 && bal_before == bal_after + 1
                ) || (
                    // accumulation happened: pot increased by amount and balance increased by amount
                    pot_after == pot_before + amount && bal_after == bal_before + amount
                )
            )
        );
    }

    // accept Ether when contract receives payout calls
    receive() external payable {}
}

