    // single public test function taking an input amount and attempting to call play
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe balances before
        uint balBeforeCaller = address(this).balance;
        uint balBeforeC = address(c).balance;

        bool reverted;
        // make the state-changing call; play is payable and takes no args
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfterCaller = address(this).balance;
        uint balAfterC = address(c).balance;

